//! polyfun against values recorded from MATLAB R2023b (printed with %.17g).
//! Generated from the verification scripts; each case runs in a fresh interpreter.

use livre_lang::{Interpreter, OutputKind, Value};

const INF: f64 = f64::INFINITY;
const NAN: f64 = f64::NAN;

/// Expected output: (variable, class, dims, real parts, imaginary parts).
type Want = (&'static str, &'static str, &'static [usize], &'static [f64], &'static [f64]);

fn same(a: f64, b: f64) -> bool {
    a == b || (a.is_nan() && b.is_nan()) || (a - b).abs() <= 1e-12 * a.abs().max(b.abs()).max(1.0)
}

/// Runs `src`; `want` is either the outputs or, with an error, MATLAB's message.
fn case(src: &str, want: &[Want], error: Option<&str>) {
    let mut it = Interpreter::new();
    let _ = it.run_source(src);
    let errors: Vec<String> = it.take_outputs().into_iter().filter_map(|o| match o.kind {
        OutputKind::Error(e) => Some(e),
        _ => None,
    }).collect();
    if let Some(msg) = error {
        assert!(errors.iter().any(|e| e.contains(msg)), "{src}: expected error {msg:?}, got {errors:?}");
        return;
    }
    assert!(errors.is_empty(), "{src}: {errors:?}");
    for &(name, class, dims, re, im) in want {
        let Some(Value::Num(m)) = it.get_var(name) else { panic!("{src}: {name} is not numeric") };
        assert_eq!(m.kind.name(), class, "{src}: class of {name}");
        assert_eq!(m.dims.as_slice(), dims, "{src}: size of {name}");
        for k in 0..m.numel() {
            assert!(same(m.data[k], re[k]) && same(m.im_at(k), im.get(k).copied().unwrap_or(0.0)), "{src}: {name}({}) = {} + {}i, MATLAB {} + {}i", k + 1, m.data[k], m.im_at(k), re[k], im.get(k).copied().unwrap_or(0.0));
        }
    }
}

