    case(r#"r__ = interp1(single(0:4),[1 3 2 5 4],[0.5 1.5]);"#, &[("r__", "single", &[1, 2], &[2.0, 2.5], &[])], None);
    case(r#"r__ = interp1(0:4,[1 3 2 5 4],[2.5 0.5],'nearest');"#, &[("r__", "double", &[1, 2], &[5.0, 3.0], &[])], None);
